def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def find_primes(limit):
    primes = []
    for num in range(2, limit+1):
        if is_prime(num):
            primes.append(num)
    return primes

# Example: Find all prime numbers up to 100
